it('reports a directory occupying a project lock path without advertising deletion as lock repair', async () => {
  const { root, paths } = await project();
  const file = path.join(paths.locksDir, 'interrupted.lock');
  await fs.mkdir(file);
  const result = await runNativeCli(['doctor', '--project-root', root, '--json']);
  const data = JSON.parse(result.stdout!).data;
  expect(data.healthy).toBe(false);
  expect(data.recovery).toMatchObject({
    code: 'lock-owner-unknown',
    affectedPaths: [file],
    recoveryArgs: null,
  });
  expect((await fs.lstat(file)).isDirectory()).toBe(true);
});

it('executes the exact recovery command emitted by the standalone doctor bundle', async () => {
  const { root, paths } = await project();
  const file = path.join(paths.locksDir, 'interrupted.lock');
  await fs.writeFile(file, '{original-writer');
  const entry = path.resolve('assets/skills/comet-native/scripts/comet-native-doctor.mjs');
  const diagnosed = spawnSync(process.execPath, [entry, '--project-root', root, '--json'], {
    encoding: 'utf8',
  });
  const data = JSON.parse(diagnosed.stdout).data;
  expect(data.recovery).toMatchObject({ code: 'lock-owner-unknown', affectedPaths: [file] });
  const recovered = spawnSync(process.execPath, [entry, ...data.recovery.recoveryArgs.slice(3)], {
    encoding: 'utf8',
  });
  expect(recovered.status, recovered.stdout || recovered.stderr).toBe(0);
  await expect(fs.access(file)).rejects.toMatchObject({ code: 'ENOENT' });
});

it('recovers an unknown Native coordinator claim through the exact emitted command without acquiring the blocked coordinator', async () => {
  const { root, paths } = await project();
  const directory = path.join(paths.locksDir, '.coordinator');
  await fs.mkdir(directory, { recursive: true });
  const file = path.join(directory, '00000000-0000-0000-0000-000000000000.claim');
  await fs.writeFile(
    file,
    JSON.stringify({
      id: 'old-coordinator',
      pid: 2_147_483_647,
      hostname: 'another-machine',
      operation: 'interrupted coordinator',
      createdAt: '2000-01-01T00:00:00.000Z',
    }),
  );
  const diagnostic = await runNativeCli(['doctor', '--repair', '--project-root', root, '--json']);
  const recovery = JSON.parse(diagnostic.stdout!).data.recovery;
  expect(recovery).toMatchObject({ code: 'lock-owner-unknown', affectedPaths: [file] });
  expect((await runNativeCli(recovery.recoveryArgs.slice(2))).exitCode).toBe(0);
  await expect(fs.access(file)).rejects.toMatchObject({ code: 'ENOENT' });
  const lock = await acquireNativeLock(paths, 'archive', 'after coordinator recovery');
  await releaseNativeLock(lock);
});

it('preserves a live project lock even when its exact token is submitted with stopped-owner confirmation', async () => {
  const { root, paths } = await project();
  const lock = await acquireNativeLock(paths, 'archive', 'live archive');
  const before = await fs.readFile(lock.file, 'utf8');
  const diagnostic = await runNativeCli(['doctor', '--repair', '--project-root', root, '--json']);
  const data = JSON.parse(diagnostic.stdout!).data;
  expect(data.recovery).toMatchObject({
    code: 'lock-active',
    recoveryArgs: null,
    owner: { id: lock.owner.id },
  });
  const rejected = await runNativeCli([
    'doctor',
    '--repair',
    '--confirmed',
    '--lock-token',
    data.findings[0].token,
    '--project-root',
    root,
    '--json',
  ]);
  expect(rejected.exitCode).not.toBe(0);
  expect(await fs.readFile(lock.file, 'utf8')).toBe(before);
  await releaseNativeLock(lock);
  expect(
    JSON.parse((await runNativeCli(['doctor', '--project-root', root, '--json'])).stdout!).data,
  ).toMatchObject({ healthy: true });
});

it('rejects a replaced lock token and preserves malformed lock bytes when explicit recovery quarantines them', async () => {
  const { root, paths } = await project();
  const lock = await acquireNativeLock(paths, 'archive', 'interrupted archive');
  await releaseNativeLock(lock);
  await fs.writeFile(lock.file, '{partial-first');
  const first = JSON.parse(
    (await runNativeCli(['doctor', '--project-root', root, '--json'])).stdout!,
  ).data.recovery;
  await fs.writeFile(lock.file, '{partial-replacement');
  expect((await runNativeCli(first.recoveryArgs.slice(2))).exitCode).not.toBe(0);
  expect(await fs.readFile(lock.file, 'utf8')).toBe('{partial-replacement');
  const current = JSON.parse(
    (await runNativeCli(['doctor', '--project-root', root, '--json'])).stdout!,
  ).data.recovery;
  expect((await runNativeCli(current.recoveryArgs.slice(2))).exitCode).toBe(0);
  await expect(fs.access(lock.file)).rejects.toMatchObject({ code: 'ENOENT' });
  const quarantined = (await fs.readdir(path.join(paths.locksDir, '.coordinator'))).filter((name) =>
    name.endsWith('.repaired'),
  );
  expect(quarantined).toHaveLength(1);
  expect(await fs.readFile(path.join(paths.locksDir, '.coordinator', quarantined[0]), 'utf8')).toBe(
    '{partial-replacement',
  );
});

it('requires the exact stopped-owner decision for an aged unknown project lock and executes its emitted recovery command', async () => {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'native-command-recovery-'));
  roots.push(root);
  execFileSync('git', ['init', '--quiet'], { cwd: root });
  await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
  const paths = await nativeProjectPaths(root, 'docs');
  await ensureNativeDirectories(paths);
  const lock = await acquireNativeLock(paths, 'archive', 'archive on another machine');
  await releaseNativeLock(lock);
  const content = JSON.stringify({
    ...lock.owner,
    hostname: 'another-machine',
    createdAt: '2000-01-01T00:00:00.000Z',
  });
  await fs.writeFile(lock.file, content);
  const ordinary = await runNativeCli(['doctor', '--repair', '--project-root', root, '--json']);
  expect(await fs.readFile(lock.file, 'utf8')).toBe(content);
  const recovery = JSON.parse(ordinary.stdout!).data.recovery as {
    code: string;
    recoveryArgs: string[];
    affectedPaths: string[];
    owner: { hostname: string };
  };
  expect(recovery).toMatchObject({
    code: 'lock-owner-unknown',
    affectedPaths: [lock.file],
    owner: { id: lock.owner.id },
  });
  expect(recovery.recoveryArgs).toContain('--lock-token');
  const repaired = await runNativeCli(recovery.recoveryArgs.slice(2));
  expect(repaired.exitCode, repaired.stdout ?? repaired.stderr).toBe(0);
  await expect(fs.access(lock.file)).rejects.toMatchObject({ code: 'ENOENT' });
});

it('diagnoses and repairs the original SDK store writer lock without changing Run history', async () => {
    const { root, name, request } = await fixture();
    const directory = path.join(
      resolveWorkspaceRuntimeRootSync(root),
      'sdk-runs/native/.runtime-store-v2',
      createHash('sha256').update(JSON.stringify(name)).digest('hex'),
    );
    const file = path.join(directory, '.write.lock');
    await fs.mkdir(directory, { recursive: true });
    await fs.writeFile(file, '{interrupted-writer');
    const original = await readNativeSdkRunRecord(root, name);
    const action = original!.actions.find(({ status }) => status === 'pending')!;
    await fs.writeFile(
      request,
      JSON.stringify({
        operation: 'claim',
        runId: name,
        actionId: action.id,
        attempt: action.attempt,
        inputHash: action.inputHash,
        executorId: 'native-host',
        sessionId: 'writer-session',
        claimToken: 'writer-session',
      }),
    );
    const refused = await runtimeDispatchCommand({
      application: 'native',
      projectRoot: root,
      request,
    });
    expect(refused.response).toMatchObject({
      status: 'failed',
      recovery: { code: 'lock-owner-unknown', affectedPaths: [file] },
    });
    const diagnosed = await runNativeCli(['doctor', name, '--project-root', root, '--json']);
    const data = JSON.parse(diagnosed.stdout!).data;
    expect(data).toMatchObject({
      healthy: false,
      recovery: { code: 'lock-owner-unknown', affectedPaths: [file] },
    });
    const repaired = await runNativeCli(data.recovery.recoveryArgs.slice(2));
    expect(repaired.exitCode, repaired.stdout ?? repaired.stderr).toBe(0);
    expect(await readNativeSdkRunRecord(root, name)).toEqual(original);
    await expect(fs.access(file)).rejects.toMatchObject({ code: 'ENOENT' });
  });

it('executes the public recovery command for the exact uncertain lock and preserves the original Run', async () => {
    const { root, name, lock } = await fixture();
    await fs.writeFile(lock, '{partial');
    const original = await readNativeSdkRunRecord(root, name);
    const diagnosed = await runNativeCli(['doctor', name, '--project-root', root, '--json']);
    expect(diagnosed.exitCode).toBe(65);
    const data = JSON.parse(diagnosed.stdout!).data as {
      recovery: {
        code: string;
        diagnosticArgs: string[];
        recoveryArgs: string[];
        preconditions: string[];
      };
    };
    expect(data.recovery).toMatchObject({ code: 'lock-owner-unknown' });
    expect(data.recovery.preconditions.length).toBeGreaterThan(0);
    expect(data.recovery.recoveryArgs).toContain('--lock-token');
    const repaired = await runNativeCli(data.recovery.recoveryArgs.slice(2));
    expect(repaired.exitCode, repaired.stdout ?? repaired.stderr).toBe(0);
    expect(await readNativeSdkRunRecord(root, name)).toEqual(original);
    await expect(fs.access(lock)).rejects.toMatchObject({ code: 'ENOENT' });
    const repeated = await runNativeCli(['doctor', name, '--project-root', root, '--json']);
    expect(JSON.parse(repeated.stdout!).data).toMatchObject({ healthy: true });
  });

it('does not steal an uncertain lock during ordinary repair and requires its exact confirmed token', async () => {
    const { root, name, lock } = await fixture();
    await fs.writeFile(lock, '{partial');
    const before = await files(root);
    const doctor = await nativeDoctorCommand([name, '--repair'], root);
    const finding = (
      doctor.data as { findings: Array<{ code: string; token: string; repairCommand: string }> }
    ).findings[0];
    expect(finding.code).toBe('sdk-projection-lock-malformed');
    expect(finding.repairCommand).toContain('--repair --confirmed --lock-token');
    expect(await files(root)).toEqual(before);
    const wrongToken = await runNativeCli(['doctor',name,'--project-root',root,'--repair','--confirmed','--lock-token','wrong-token','--json']);
    expect(wrongToken.exitCode).not.toBe(0);
    expect(await files(root)).toEqual(before);
    const run = await readNativeSdkRunRecord(root, name);
    const repaired = await nativeDoctorCommand(
      [name, '--repair', '--confirmed', '--lock-token', finding.token],
      root,
    );
    expect(repaired.data).toMatchObject({ healthy: true, repaired: true });
    expect(await readNativeSdkRunRecord(root, name)).toEqual(run);
    expect((await nativeStatusCommand([name], root)).exitCode).toBe(0);
  });

it('repairs released real writer metadata without deleting or replacing its reusable SQLite database', async () => {
  const f = await fixture(),
    lease = await acquireNativeLock(f.paths, 'archive', 'SIMULATED local fixture writer'),
    metadata = await fs.readFile(lease.file, 'utf8');
  await releaseNativeLock(lease);
  const database = lease.file + '.sqlite',
    original = await fs.stat(database, { bigint: true });
  await fs.writeFile(lease.file, metadata);
  const lock = (await inspectNativeProjectLocks(f.paths)).find((l) => l.file === lease.file)!;
  expect(lock.status).toBe('stale');
  await repairNativeProjectLock(f.paths, lock.token!, true);
  await expect(fs.stat(lease.file)).rejects.toMatchObject({ code: 'ENOENT' });
  const after = await fs.stat(database, { bigint: true });
  expect({ dev: after.dev, ino: after.ino }).toEqual({
    dev: original.dev,
    ino: original.ino,
  });
  const next = await acquireNativeLock(f.paths, 'archive', 'SIMULATED next local writer');
  await releaseNativeLock(next);
});

it('never repairs away a real live writer even when its exact metadata token is confirmed', async () => {
  const f = await fixture(),
    lease = await acquireNativeLock(f.paths, 'archive', 'SIMULATED live local writer');
  try {
    const before = await fs.readFile(lease.file, 'utf8'),
      lock = (await inspectNativeProjectLocks(f.paths)).find((l) => l.file === lease.file)!;
    expect(lock.status).toBe('active');
    await expect(repairNativeProjectLock(f.paths, lock.token!, true)).rejects.toThrow();
    expect(await fs.readFile(lease.file, 'utf8')).toBe(before);
  } finally {
    await releaseNativeLock(lease);
  }
});

it('serializes root moves with archive operations through the global lock', async () => {
    await seedNativeRoot(projectRoot, '.');
    const paths = await nativeProjectPaths(projectRoot, '.');
    const archiveGlobalLock = await acquireNativeLock(paths, 'root-move', 'archive active-change');
    try {
      await expect(moveNativeRoot({ projectRoot, toArtifactRoot: 'docs' })).rejects.toThrow(
        /Native lock is busy/u,
      );
    } finally {
      await releaseNativeLock(archiveGlobalLock);
    }
  });

it('refuses to copy any unresolved operation lock into the destination root', async () => {
    await seedNativeRoot(projectRoot, '.');
    const paths = await nativeProjectPaths(projectRoot, '.');
    const staleArchiveLock = await acquireNativeLock(
      paths,
      'archive',
      'archive interrupted-change',
    );
    try {
      await expect(moveNativeRoot({ projectRoot, toArtifactRoot: 'docs' })).rejects.toThrow(
        'must be diagnosed before moving',
      );
      expect((await readProjectConfig(projectRoot))?.native).toEqual({
        artifact_root: '.',
        language: 'en',
        clarification_mode: 'batch',
        archive_confirmation: 'automatic',
        max_verify_failures: 5,
      });
      await expect(fs.access(path.join(projectRoot, 'docs', 'comet'))).rejects.toMatchObject({
        code: 'ENOENT',
      });
    } finally {
      await releaseNativeLock(staleArchiveLock);
    }
  });

it('does not remove an actually held transition writer even when its exact token is confirmed', async () => {
  const f = await currentJournal(),
    lock = await acquireNativeLock(
      f.paths,
      'transition-' + f.name,
      'actual live writer for WAL fixture',
    );
  try {
    const d = await inspectNativeLockRecovery(lock.file);
    expect(d.status).toBe('active');
    expect(d.token).toBeTruthy();
    await expect(repairNativeProjectLock(f.paths, d.token!, true)).rejects.toThrow();
    expect(await inspectNativeLockRecovery(lock.file)).toMatchObject({
      status: 'active',
      token: d.token,
    });
    expect(await fs.readFile(f.wal, 'utf8')).toContain(f.journal.id);
  } finally {
    await releaseNativeLock(lock);
  }
  await continueNativeTransition(f.paths, f.name);
  expect(await inspectPendingNativeTransition(f.paths, f.name)).toBeNull();
});

it('requires explicit confirmation for the original real writer metadata before finishing its WAL', async () => {
  const f = await currentJournal();
  await fs.mkdir(f.paths.locksDir, { recursive: true });
  const lock = path.join(f.paths.locksDir, 'transition-' + f.name + '.lock');
  await fs.writeFile(
    lock,
    JSON.stringify({
      id: 'original-writer',
      createdAt: '2026-07-15T00:00:00.000Z',
      operation: 'continue original WAL',
    }),
  );
  await expect(continueNativeTransition(f.paths, f.name)).rejects.toThrow(
    /Legacy lock requires confirmation/,
  );
  const diagnosis = await inspectNativeLockRecovery(lock);
  expect(diagnosis.token).toBeTruthy();
  await expect(repairNativeProjectLock(f.paths, diagnosis.token!, false)).rejects.toThrow();
  expect(await fs.readFile(f.wal, 'utf8')).toContain(f.journal.id);
  await repairNativeProjectLock(f.paths, diagnosis.token!, true);
  await continueNativeTransition(f.paths, f.name);
  expect(await inspectPendingNativeTransition(f.paths, f.name)).toBeNull();
  expect(
    (await readNativeTrajectory(f.dir, f.journal.nextRun.trajectoryRef)).filter(
      (e) => e.type === 'state_transitioned',
    ),
  ).toHaveLength(1);
});

