it('preserves both original root and transition writer metadata until each explicit confirmed takeover', async () => {
  const f = await currentJournal();
  await fs.mkdir(f.paths.locksDir, { recursive: true });
  const entries = [
    ['transition-' + f.name, 'old-transition-writer'],
    ['root-move', 'old-root-writer'],
  ];
  for (const [name, id] of entries)
