      path.join(f.paths.locksDir, name + '.lock'),
      JSON.stringify({
        id,
        createdAt: '2026-07-15T00:00:00.000Z',
        operation: 'original real WAL write boundary',
      }),
    );
  const before = await fs.readFile(f.wal, 'utf8');
  for (const [name] of entries) {
    const file = path.join(f.paths.locksDir, name + '.lock'),
      d = await inspectNativeLockRecovery(file);
    expect(d.token).toBeTruthy();
    await expect(repairNativeProjectLock(f.paths, d.token!, false)).rejects.toThrow();
    await repairNativeProjectLock(f.paths, d.token!, true);
  }
  expect(await fs.readFile(f.wal, 'utf8')).toBe(before);
  await continueNativeTransition(f.paths, f.name);
  expect(
    (await readNativeTrajectory(f.dir, f.journal.nextRun.trajectoryRef)).filter(
      (e) => e.type === 'state_transitioned',
